functions.OrderPush:
function OrderPush(){
	var gridObj = $("#extAppsFailedOrderGrid");
	var rowIds =  gridObj.jqGrid('getGridParam', 'selarrrow');

	if(rowIds==0){
		window.parent.showAlert('Please select atleast one row to proceed');
		return false;
	}

	var transmitdetailkeys='';
	var n=rowIds.length;
	for (var i = 0; i<n; i++) {
		transmitdetailkeys+=gridObj.jqGrid("getCell", rowIds[i], "transmitdetKey")+',';
	}


	window.parent.blockUIStart();
	window.setTimeout(function(){
		var retVal = $.ajax({
			url : "orderPushextApps",

			type : "POST",
			data : {
				transmitdetailkey:transmitdetailkeys,
				flag:"orderPush"
						},

			dataType : "json",
			async : false
		}).responseText;

		retVal = jQuery.parseJSON(retVal);

		if(retVal != null){
			if(retVal.jsonMessage == null){
				rewardDTO = retVal.searchDTO;
				if(rewardDTO != null){
				        window.parent.blockUIEnd();
						window.parent.showAlert(rewardDTO.jsonMessage);
						callSearch();
					}else{
						 window.parent.blockUIEnd();
						window.parent.showAlert(rewardDTO.jsonMessage);
					}
				}

		}
		},2000);


}

