function fetchRewardMasterData(rewardType){


	var retVal = $.ajax({
		url : "populateExtAppsFailedOrderGrid?REQ_SEARCH_FLAG=true",

		type : "POST",
		data : {
			rewardType : '',
		},
		dataType : "json",
		async : false
	}).responseText;
	var typetempmap=new Object();
	retVal = jQuery.parseJSON(retVal);
	sourceMap=retVal.extAppdescMap;
	extappMap=sourceMap;
	statusMap=retVal.statusMap;
	var MasterData = sourceMap;
	var vals4Cmb = new Array;
	if (MasterData != null) {
		var counter = 0;
		vals4Cmb[counter++] = new CodeValueStruct("-1",'--- Select ---');
		for ( var i in MasterData) {
			if(MasterData.hasOwnProperty(i))
				typetempmap[i]=MasterData[i];
			vals4Cmb[counter++] = new CodeValueStruct(
					i, MasterData[i]);
		}

	}fillCombo('gs_channelCode', vals4Cmb);
	if(statusMap!=null){
		var typetempmap=new Object();
		var MasterData = statusMap;
		var vals4Cmb = new Array;
		if (MasterData != null) {
			var counter = 0;
			vals4Cmb[counter++] = new CodeValueStruct("-1",'--- Select ---');
			for ( var i in MasterData) {
				if(MasterData.hasOwnProperty(i))
					typetempmap[i]=MasterData[i];
				vals4Cmb[counter++] = new CodeValueStruct(
						i, MasterData[i]);
			}

		}
		fillCombo('gs_statusdesc', vals4Cmb);

	}




}

