functions.callSearch:
function callSearch() {

		$("#extAppsFailedOrderGrid").jqGrid('setGridParam', {
			datatype : 'json',
			page : 1
		});
		$("#extAppsFailedOrderGrid").jqGrid('setGridParam', {
			postData : {
				orderNumber : $("#gs_orderNo").val(),
				fromInvoiceDate : $("#fromCreateDate").val(),
				toInvoiceDate : $("#toCreateDate").val(),
				channelCode :$("#gs_channelCode").val(),
				fromUpdateDate: $("#fromUpdateDate").val(),
				toUpdateDate: $("#toUpdateDate").val(),
				status:$("#gs_statusdesc").val(),
				invoiceNumber:$("#gs_invoiceNumber").val(),
				REQ_SEARCH_FLAG : true,
				doFetchCount : false
			},
			url : "populateExtAppsFailedOrderGrid",
			search : true
		}).trigger('reloadGrid');
	}

