functions.genricSearchGridResized:
function genricSearchGridResized() {
		var gridObj = $("#extAppsFailedOrderGrid");

		var gridHeight = window.parent.getParentHeight()-128;		

		var gridWidth = $(window).width()-18;
		if(gridWidth<270)
			gridWidth=270;


		gridObj.jqGrid('setGridParam', { shrinkToFit: $(window).width()<992 ? false : true });
		try {
			if($(window).width()<992) {
				if(oldWidth>992) {
					gridObj.trigger('reloadGrid');
				}
				//gridObj.jqGrid('hideCol','status');
			} else {
				if(oldWidth<992) {
					gridObj.trigger('reloadGrid');
				}
				//gridObj.jqGrid('showCol','status');
			}
		} catch (e) {}


		gridObj.jqGrid('setGridWidth',gridWidth);		
		$("#gbox_"+gridObj[0].id+" .ui-jqgrid-bdiv").css("height",gridHeight+"px").css('overflow-x',($(window).width()<992 ?'auto':'hidden'));
		  oldWidth=gridWidth;

	}
